const D = (x) => Number(x);
const out = [];
const p = (...a) => out.push(a.join(" "));

const merc = [1800000,1200000,1500000,1500000,2200000,3100000,1400000,950000,880000,600000,1300000];
const decl = [520000,380000,410000,410000,600000,900000,350000,300000,280000,150000,420000];
const alug = [7200,5200,9800,9800,14000,22000,0,4300,4100,0,8500];
const loc  = [1,1,1,1,1,1,0,1,1,0,1];
const s = a => a.reduce((x,y)=>x+y,0);
const s9 = (a) => a.reduce((x,y,i)=>x+(loc[i]?y:0),0);

p("mercado total", s(merc));
p("decl total", s(decl));
p("aluguel mes", s(alug), "ano", s(alug)*12);
p("merc9", s9(merc), "decl9", s9(decl));
p("acervo", s(merc)+2100000);

p("ITBI11mkt", 16430000*0.03, "ITBI9mkt", 14430000*0.03, "ITBI11decl", 4720000*0.03);
p("excesso", 16430000-4720000, "x3%", (16430000-4720000)*0.03);

const diff11 = 16430000-4720000, diff9 = 14430000-4220000;
p("diff11", diff11, "15%", diff11*0.15, "22.5%", diff11*0.225);
p("diff9", diff9, "15%", diff9*0.15, "22.5%", diff9*0.225);

const rent=84900, fee=rent*0.08;
p("comissao mes", fee, "ano", fee*12);
const bpf = rent-fee;
const irpf = 0.275*bpf - 908.73;
p("base pf", bpf, "ir mes", irpf.toFixed(2), "ir ano", (irpf*12).toFixed(2), "pct", ((irpf*12)/(rent*12)*100).toFixed(2));

const pres = rent*0.32;
const irpj = 0.15*pres + 0.10*(pres-20000);
const csll = 0.09*pres;
const pis = 0.0365*rent;
const pjm = irpj+csll+pis;
p("pres", pres, "irpj", irpj.toFixed(2), "csll", csll.toFixed(2), "pis", pis.toFixed(2), "pj mes", pjm.toFixed(2), "pj ano", (pjm*12).toFixed(2), "carga", (pjm/rent*100).toFixed(4));
const cash = rent - pjm - fee;
const exc = cash-50000;
const irrf = exc*0.10;
p("cash", cash.toFixed(2), "exced", exc.toFixed(2), "irrf mes", irrf.toFixed(2), "irrf ano", (irrf*12).toFixed(2));
const ciclo = pjm*12 + irrf*12;
p("ciclo ano", ciclo.toFixed(2), "pct", (ciclo/(rent*12)*100).toFixed(4));
const econ = irpf*12 - ciclo;
p("economia", econ.toFixed(2));
p("payback432900", (432900/econ).toFixed(3), "payback492900", (492900/econ).toFixed(3));

p("itcmd", 16430000*0.04, 14430000*0.04, 4720000*0.04);

const acervo=18530000, half=acervo/2, sixth=acervo/6;
p("meia", half, "sexto", sixth.toFixed(2));
p("pct quotas 3.088.333/14.430.000", (sixth/14430000*100).toFixed(4));
p("itcmd marcos", (sixth*0.04).toFixed(2), "0.2140*577200", 577200*0.2140);
p("R+P", (577200 - sixth*0.04).toFixed(2));
p("entradas11", 492900+657200, "9", 432900+577200);
p("14.53% vs ciclo: lib 14.53, nosso", (ciclo/(rent*12)*100).toFixed(2));
return out.join("\n");

